def invert_filtered_positive(d):
    result = {}
    for k, v in d.items():
        if v > 0:
            result.setdefault(v, []).append(k)
    for v in result:
        result[v].sort()
    return result

def running_max(lst):
    result = []
    cur_max = None
    for x in lst:
        if cur_max is None or x > cur_max:
            cur_max = x
        result.append(cur_max)
    return result

def count_leap_years_in_range(y1, y2):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    return sum(1 for y in range(y1, y2 + 1) if is_leap(y))

def bucket_sort_into_ranges(nums, boundaries):
    k = len(boundaries) - 1
    buckets = [[] for _ in range(k)]
    for v in nums:
        for i in range(k):
            lo = boundaries[i]
            hi = boundaries[i + 1]
            if i == k - 1:
                if lo <= v <= hi:
                    buckets[i].append(v)
                    break
            else:
                if lo <= v < hi:
                    buckets[i].append(v)
                    break
    for b in buckets:
        b.sort()
    return buckets

