import math

def count_common_divisors(a, b):
    g = math.gcd(a, b)
    count = 0
    i = 1
    while i * i <= g:
        if g % i == 0:
            count += 1
            if i != g // i:
                count += 1
        i += 1
    return count

def sort_by_vowel_count(words):
    def vowel_count(w):
        return sum(1 for c in w if c.lower() in 'aeiou')
    return sorted(words, key=lambda w: (vowel_count(w), w))

def is_valid_parity_bit_string(s):
    if len(s) < 2:
        return False
    if any(c not in '01' for c in s):
        return False
    return s.count('1') % 2 == 0

def largest_number_with_digit_sum(s, d):
    if d <= 0:
        return -1
    if s < 1 or s > 9 * d:
        return -1
    digits = []
    remaining = s
    for i in range(d):
        digit = min(9, remaining)
        digits.append(digit)
        remaining -= digit
    return int(''.join(str(x) for x in digits))

def tokenize_camel_case(s):
    if not s:
        return []
    words = []
    current = s[0]
    for c in s[1:]:
        if c.isupper():
            words.append(current)
            current = c
        else:
            current += c
    words.append(current)
    return words

def smart_truncate(s, maxlen):
    if len(s) <= maxlen:
        return s
    limit = maxlen - 3
    if limit <= 0:
        return s[:maxlen]
    prefix = s[:limit]
    last_space = prefix.rfind(' ')
    if last_space == -1:
        return s[:maxlen]
    return prefix[:last_space] + '...'

def is_balanced_ignoring_whitespace(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    opens = set(pairs.values())
    closes = set(pairs.keys())
    stack = []
    for c in s:
        if c in ' \t\n':
            continue
        if c in opens:
            stack.append(c)
        elif c in closes:
            if not stack or stack[-1] != pairs[c]:
                return False
            stack.pop()
        else:
            return False
    return len(stack) == 0

def kth_smallest_abs_value(nums, k):
    ordered = sorted(nums, key=lambda x: (abs(x), x))
    return ordered[k - 1]

def time_period_label(hour):
